using System;
using System.Runtime.Versioning;
using MessagePack.Formatters;

public class A5_F3_ReferencedAssemblyFormatterRegistrationTests(ITestOutputHelper logger)
{
    [Fact]
    public void A5_F3_GeneratedResolverReturnsFormatterForReferencedAssemblyType()
    {
        IMessagePackFormatter<FrameworkName?>? formatter = GeneratedMessagePackResolver.Instance.GetFormatter<FrameworkName?>();
        Assert.NotNull(formatter);
        Assert.IsType<ExternalFrameworkNameFormatter>(formatter);
    }

    [Fact]
    public void A5_F3_RoundtripWithGeneratedResolverWithoutExtraSetup()
    {
        MessagePackSerializerOptions options = MessagePackSerializerOptions.Standard.WithResolver(GeneratedMessagePackResolver.Instance);
        FrameworkName value = new FrameworkName(".NETFramework", new Version(4, 7, 2));

        byte[] serialized = MessagePackSerializer.Serialize(value, options);
        logger.WriteLine(MessagePackSerializer.ConvertToJson(serialized, options));
        FrameworkName? after = MessagePackSerializer.Deserialize<FrameworkName?>(serialized, options);

        Assert.NotNull(after);
        Assert.Equal(value, after);
    }

    /// <remarks>
    /// This formatter targets a type defined in a referenced assembly and is intentionally NOT included in any resolver.
    /// The generated resolver is expected to pick it up automatically.
    /// </remarks>
    internal class ExternalFrameworkNameFormatter : IMessagePackFormatter<FrameworkName?>
    {
        public FrameworkName? Deserialize(ref MessagePackReader reader, MessagePackSerializerOptions options)
        {
            if (reader.TryReadNil())
            {
                return null;
            }

            string? fullName = reader.ReadString();
            return fullName is null ? null : new FrameworkName(fullName);
        }

        public void Serialize(ref MessagePackWriter writer, FrameworkName? value, MessagePackSerializerOptions options)
        {
            if (value is null)
            {
                writer.WriteNil();
            }
            else
            {
                writer.Write(value.FullName);
            }
        }
    }
}
